TRAIN_MEANS = {"age": 42.0, "income": 58.0, "tenure": 12.0}
SERVE_MEANS = {"age": 43.0, "income": 71.0, "tenure": 11.5}
THRESHOLD = 0.10

def relative_drift(train_mean, serve_mean):
    return abs(serve_mean - train_mean) / train_mean

def check_features(train, serve, threshold):
    return sorted(
        name for name in train
        if relative_drift(train[name], serve[name]) > threshold
    )

drifted = check_features(TRAIN_MEANS, SERVE_MEANS, THRESHOLD)
for feature in sorted(TRAIN_MEANS):
    d = relative_drift(TRAIN_MEANS[feature], SERVE_MEANS[feature])
    status = "DRIFT" if feature in drifted else "OK"
    print(f"{feature}: drift={d:.3f} {status}")
print(f"drifted features: {len(drifted)}")
print("action: rollback" if len(drifted) > 0 else "action: none")

assert abs(relative_drift(58.0, 71.0) - 0.2241379) < 1e-6
assert abs(relative_drift(42.0, 43.0) - 0.0238095) < 1e-6
assert check_features(TRAIN_MEANS, SERVE_MEANS, 0.10) == ["income"]
assert check_features(TRAIN_MEANS, SERVE_MEANS, 0.30) == []
assert check_features(TRAIN_MEANS, SERVE_MEANS, 0.02) == ["age", "income", "tenure"]
